Tool response:
Tool: create_distribution_account
Description: Create Distribution Account
Parameters:
    {
      "type": "object",
      "properties": {
        "name": {
          "type": "string",
          "title": "Name"
        },
        "contact_name": {
          "type": "string",
          "title": "Contact Name"
        },
        "phone": {
          "type": "string",
          "title": "Phone"
        },
        "email": {
          "type": "string",
          "title": "Email"
        },
        "delivery_address": {
          "type": "string",
          "title": "Delivery Address"
        },
        "credit_limit": {
          "type": "number",
          "title": "Credit Limit"
        }
      },
