Tool response:
Tool: create_new_order
Description: Create New Order
Parameters:
    {
      "type": "object",
      "properties": {
        "account_id": {
          "type": "integer",
          "title": "Account Id"
        },
        "created_by": {
          "type": "integer",
          "title": "Created By"
        },
        "delivery_date": {
          "type": "string",
          "title": "Delivery Date"
        },
        "items": {
          "items": {
            "properties": {
              "product_id": {
                "type": "integer",
                "title": "Product Id"
              },
              "quantity": {
                "type": "integer",
                "title": "Quantity"
              },
              "unit_price": {
                "type": "number",
                "title": "Unit Price"
              },
              "keg_deposit_per_unit": {
                "anyOf": [
                  {
                    "type": "number"
                  },
                  {
                    "type": "null"
                  }
                ],
                "title": "Keg Deposit Per Unit",
                "default": 0.0
              }
            },
            "type": "object",
            "required": [
              "product_id",
              "quantity",
              "unit_price"
            ],
            "title": "OrderItemCreate"
          },
          "type": "array",
          "title": "Items"
        }
      },
      "required": [
        "account_id",
        "created_by",
        "delivery_date",
        "items"
      ]
    }

